import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public int longestValidParentheses(String s) {
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(-1);
        int best = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '(') {
                stack.push(i);
            } else {
                stack.pop();
                if (stack.isEmpty()) {
                    stack.push(i);
                } else {
                    best = Math.max(best, i - stack.peek());
                }
            }
        }
        return best;
    }
}

class Solution {
    public int longestValidParentheses(String s) {
        int[] dp = new int[s.length()];
        int best = 0;
        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) != ')') {
                continue;
            }
            if (s.charAt(i - 1) == '(') {
                dp[i] = 2 + (i >= 2 ? dp[i - 2] : 0);
            } else {
                int match = i - dp[i - 1] - 1;
                if (match >= 0 && s.charAt(match) == '(') {
                    dp[i] = dp[i - 1] + 2 + (match >= 1 ? dp[match - 1] : 0);
                }
            }
            best = Math.max(best, dp[i]);
        }
        return best;
    }
}

class Solution {
    public int longestValidParentheses(String s) {
        int best = 0;
        int left = 0;
        int right = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '(') {
                left++;
            } else {
                right++;
            }
            if (left == right) {
                best = Math.max(best, 2 * right);
            } else if (right > left) {
                left = 0;
                right = 0;
            }
        }

        left = 0;
        right = 0;
        for (int i = s.length() - 1; i >= 0; i--) {
            if (s.charAt(i) == '(') {
                left++;
            } else {
                right++;
            }
            if (left == right) {
                best = Math.max(best, 2 * left);
            } else if (left > right) {
                left = 0;
                right = 0;
            }
        }
        return best;
    }
}

import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public int longestValidParentheses(String s) {
        boolean[] matched = new boolean[s.length()];
        Deque<Integer> opens = new ArrayDeque<>();
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '(') {
                opens.push(i);
            } else if (!opens.isEmpty()) {
                int open = opens.pop();
                matched[open] = true;
                matched[i] = true;
            }
        }

        int best = 0;
        int run = 0;
        for (boolean ok : matched) {
            if (ok) {
                run++;
                best = Math.max(best, run);
            } else {
                run = 0;
            }
        }
        return best;
    }
}
